def c(code,system,en,ru,sev,causes,steps,tools,related,symptoms=None,note=None):
    d=dict(code=code,system=system,title={'en':en,'ru':ru},severity=sev,
           symptoms=symptoms or [],causes=[{'text':t,'likelihood':l} for t,l in causes],
           steps=steps,tools=tools,related=related)
    if note: d['note']=note
    return d
